import React from 'react';
import { makeStyles } from '@material-ui/core/styles';
import Table from '@material-ui/core/Table';
import TableBody from '@material-ui/core/TableBody';
import TableCell from '@material-ui/core/TableCell';
import TableContainer from '@material-ui/core/TableContainer';
import TableHead from '@material-ui/core/TableHead';
import TableRow from '@material-ui/core/TableRow';
import Typography from '@material-ui/core/Typography';
import ListDropDown from 'views/admin/Common/ListDropDown';
import Page from 'views/admin/Common/Pagination';
import { Paper } from '@material-ui/core';
import Skeleton from '@material-ui/lab/Skeleton';
import CustomInput from './CustomInput.jsx';
import EmptyState from './EmptyState';
import colors from 'config/colors.js';

const useRowStyles = makeStyles({
  root: {
    '& > *': {
      borderBottom: 'unset',
    },
  },
});

function Row(props) {
  const {
    item,
    keyIndex,
    bodyColumns,
    idName,
    dropDownActions,
    fetchItem,
    deleteItem,
    //dataLength,
    cellPadding,
    showViewOnHover,
    viewItem,
    viewStudentReport,
    viewStudentTaskAssignmentReport,
    viewStudentProgressReport,
    tableHeaders,
    enableSearch,
    searchFields,
    handleSearchChange,
    renderRowExtra,
    rowStyle,
    // test,
  } = props;
  const classes = useRowStyles();
  const [showView, setShowView] = React.useState(false);
  return (
    <React.Fragment key={keyIndex}>
      {enableSearch && keyIndex === 0 && (
        <TableRow>
          {tableHeaders.map((el, i) => {
            const matchItem = searchFields.find(dto => dto?.order === i);
            return matchItem ? (
              <TableCell key={i} align="left">
                <CustomInput name={matchItem.label} onChange={handleSearchChange} placeholder="Search..." />
              </TableCell>
            ) : (
              <TableCell />
            );
          })}
        </TableRow>
      )}
      <TableRow
        className={classes.root}
        style={{
          borderBottom: '0.5px solid lightgrey',
          ...rowStyle,
          //...(dataLength > 1 && { backgroundColor: keyIndex % 2 === 0 ? 'rgba(0,0,0,.05)' : 'white' }),
        }}
        onMouseEnter={() => showViewOnHover && setShowView(true)}
        onMouseLeave={() => setShowView(false)}>
        {bodyColumns
          .filter(dto => dto && dto !== 'action')
          .map((el, i) => {
            return (
              <TableCell
                key={i}
                align={el === 'actionItem' ? 'center' : 'left'}
                style={cellPadding ? { ...cellPadding } : { paddingTop: 15, paddingBottom: 15 }}>
                {item ? (
                  <>
                    {item[el]}
                    {!i && showView && (
                      <>
                        <br />
                        <span
                          href="#"
                          style={{ cursor: 'pointer', color: colors.aTag, fontWeight: 'bold' }}
                          onClick={() => viewItem(item[idName])}>
                          View
                        </span>
                      </>
                    )}
                  </>
                ) : null}
              </TableCell>
            );
          })}
        {bodyColumns.includes('action') ? (
          <TableCell align="center">
            <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 10 }}>
              {renderRowExtra && renderRowExtra(item)}
              <ListDropDown
                actionList={dropDownActions}
                item={item}
                fetchItem={() => fetchItem(item[idName])}
                deleteItem={() => deleteItem(item[idName])}
                viewItem={() => viewItem(item[idName])}
                viewStudentReport={() => viewStudentReport(item[idName])}
                viewStudentTaskAssignmentReport={() => viewStudentTaskAssignmentReport(item[idName])}
                viewStudentProgressReport={() => viewStudentProgressReport(item[idName])}
              />
            </div>
          </TableCell>
        ) : null}
      </TableRow>
    </React.Fragment>
  );
}

export default function MuiTable({
  tableHeaders = [],
  tableBodyData = { content: [] },
  bodyColumns = 0,
  idName = null,
  dropDownActions = [],
  fetchItem = () => true,
  deleteItem = () => true,
  fetchPageData = () => true,
  hidePagination = false,
  cellPadding = null,
  isLoading = false,
  showViewOnHover = false,
  viewItem = () => true,
  viewStudentReport = () => true,
  viewStudentTaskAssignmentReport = () => true,
  viewStudentProgressReport = () => true,
  enableSearch = false,
  searchFields = [],
  handleSearchChange = () => true,
  renderRowExtra = null,
  // (item) => style for that row, e.g. to highlight one of the rows
  getRowStyle = null,
}) {
  return (
    <TableContainer component={Paper} style={{ padding: 5 }}>
      <Table size="small" aria-label="collapsible table">
        <TableHead>
          <TableRow>
            {tableHeaders
              ?.filter(dto => dto)
              .map((el, k) => {
                return (
                  <TableCell
                    key={k}
                    align={tableHeaders.length === k + 1 && el === 'Action' ? 'center' : 'left'}
                    className="text-primary"
                    style={{ paddingTop: 10, paddingBottom: 12 }}>
                    <Typography variant="h6" style={{ fontWeight: 'bold' }}>
                      {el}
                    </Typography>
                  </TableCell>
                );
              })}
          </TableRow>
        </TableHead>
        <TableBody>
          {isLoading ? (
            new Array(16).fill(0).map((el, i) => (
              <TableRow key={i}>
                {tableHeaders.map((e2, i1) => (
                  <TableCell key={i1}>
                    <Skeleton animation="wave" variant="text" />
                  </TableCell>
                ))}
              </TableRow>
            ))
          ) : tableBodyData?.content?.length > 0 ? (
            tableBodyData?.content
              ?.filter(fItem => fItem)
              .map((item, i) => (
                <Row
                  key={i}
                  keyIndex={i}
                  item={item}
                  bodyColumns={bodyColumns}
                  colSpanLen={tableHeaders.length}
                  dropDownActions={dropDownActions}
                  idName={idName}
                  fetchItem={fetchItem}
                  deleteItem={deleteItem}
                  dataLength={tableBodyData?.content?.length}
                  cellPadding={cellPadding}
                  showViewOnHover={showViewOnHover}
                  viewItem={viewItem}
                  viewStudentReport={viewStudentReport}
                  viewStudentTaskAssignmentReport={viewStudentTaskAssignmentReport}
                  viewStudentProgressReport={viewStudentProgressReport}
                  tableHeaders={tableHeaders}
                  enableSearch={enableSearch}
                  searchFields={searchFields}
                  handleSearchChange={handleSearchChange}
                  renderRowExtra={renderRowExtra}
                  rowStyle={getRowStyle ? getRowStyle(item) : undefined}
                />
              ))
          ) : (
            <TableRow>
              <TableCell colSpan={tableHeaders.length} style={{ borderBottom: 'none' }}>
                <EmptyState compact bare title="Nothing to show here yet" />
              </TableCell>
            </TableRow>
          )}
        </TableBody>
      </Table>
      {tableBodyData?.content?.length > 0 &&
      (tableBodyData?.totalPages || tableBodyData?.page?.totalPages) &&
      !hidePagination ? (
        <Page
          fetchPageData={fetchPageData}
          style={{ marginTop: 15, marginLeft: 0, marginRight: 0 }}
          {...tableBodyData}
          isLoading={isLoading}
        />
      ) : null}
    </TableContainer>
  );
}
