import React from 'react';
import { connect } from 'react-redux';
import { Row, Col } from 'reactstrap';
import { guardianTableHead } from 'variables/general';

import {
  fetchAllGuardiansService,
  saveGuardianService,
  fetchGuardianService,
  updateGuardianService,
  deleteGuardianService,
  fetchUnMappedGuardiansService,
} from 'actions/admin/guardians';
import GuardianFormModal from './components/GuardianFormModal.jsx';
import {
  formResMessage,
  formUsernameFromEmail,
  getGlobalCurrentBatchUtils,
  getGlobalSchoolUtils,
  usernameTextColor,
} from '../../../utils/commonFunc.js';
import { store } from '../../../index.js';
import { showToast } from '../../../actions/admin/auth.js';
import CustomButton from '../../../components/CustomButton.jsx';
import MuiTable from '../Common/MuiTable.jsx';
import Radio from '@material-ui/core/Radio';
import colors from 'config/colors';

class GuardianPage extends React.Component {
  constructor() {
    super();
    this.state = {
      schoolId: 0,
      isModalOpen: false,
      pageParams: {
        page: 1,
        size: 10,
      },
      activeTab: 0,
      // loaders
      guardiansFetching: false,
    };
  }

  isLoading = (name, value) => this.setState({ [name]: value });

  componentDidMount() {
    const globalSchool = getGlobalSchoolUtils();
    if (globalSchool) {
      this.setState({ schoolId: globalSchool.schoolId }, () => {
        this.fetchAllGuardians();
      });
    } else {
      this.showWarning('Please select School', 'warning');
    }
  }

  fetchAllGuardians = async refetchAgain => {
    const { batchId } = getGlobalCurrentBatchUtils();
    if (batchId && (!this.props.guardiansData?.content?.length || refetchAgain)) {
      this.isLoading('guardiansFetching', true);
      await this.props.fetchAllGuardians({
        schoolId: this.state.schoolId,
        batchId,
        token: this.props.loggedUserToken,
        pageParams: this.state.pageParams,
      });
      this.isLoading('guardiansFetching', false);
    }
  };

  formModalOpen = () => this.setState({ isModalOpen: true });

  formModalClose = () => {
    this.setState({ isModalOpen: false });
  };

  saveGuardian = data => {
    data.school = { schoolId: this.state.schoolId };
    return this.props.saveGuardian({ postData: data, token: this.props.loggedUserToken });
  };

  fetchGuardian = guardianId => {
    return this.props.fetchGuardian({ guardianId, token: this.props.loggedUserToken }).then(() => this.formModalOpen());
  };

  updateGuardian = data => {
    return this.props.updateGuardian({
      guardianId: data.guardianId,
      postData: data,
      token: this.props.loggedUserToken,
    });
  };

  guardianUpdateSuccess = actionParam => {
    this.setState({ isModalOpen: false });
    this.showWarning(
      actionParam === 'add' ? 'Guardian added successfully' : 'Guardian Updated successfully',
      'success'
    );
    this.fetchUnMappedGuardians();
    this.fetchAllGuardians(true);
  };

  showWarning = (message, type) => {
    store.dispatch(showToast(message, type));
  };

  deleteGuardian = guardianId => {
    return this.props
      .deleteGuardian({ guardianId, token: this.props.loggedUserToken })
      .then(() => {
        this.fetchUnMappedGuardians();
        this.fetchAllGuardians(true);
      })
      .catch(err => {
        this.showWarning(formResMessage(err), 'error');
      });
  };

  fetchPageData = page => {
    if (page !== this.state.pageParams.page) {
      this.setState(
        {
          pageParams: {
            ...this.state.pageParams,
            page,
          },
        },
        () => {
          this.fetchAllGuardians(true);
        }
      );
    }
  };

  fetchUnMappedGuardians = refetchAgain => {
    if (!this.props.unMappedGuardianList.length || refetchAgain) {
      this.props.fetchUnMappedGuardians({
        schoolId: this.state.schoolId,
        token: this.props.loggedUserToken,
      });
    }
  };

  toggle = tab => {
    if (this.state.activeTab !== tab) {
      this.setState({ activeTab: tab });
      if (tab === 1) {
        this.fetchUnMappedGuardians();
      }
    }
  };

  render() {
    const { isModalOpen, activeTab, guardiansFetching } = this.state;
    const { guardiansData, guardian, unMappedGuardianList } = this.props;

    const choiceCard = (checked, label, description, onClick) => (
      <div
        onClick={onClick}
        style={{
          display: 'flex',
          alignItems: 'flex-start',
          gap: 4,
          padding: '8px 12px',
          borderRadius: 8,
          border: `1.5px solid ${checked ? colors.accent : '#e0e0e0'}`,
          backgroundColor: checked ? '#F5EDFB' : '#fff',
          cursor: 'pointer',
        }}>
        <Radio checked={checked} size="small" style={{ color: colors.accent, padding: 2, marginTop: -2 }} />
        <div>
          <div style={{ fontWeight: 'bold', fontSize: 13 }}>{label}</div>
          <div style={{ fontSize: 12, color: '#6b778a', marginTop: 2 }}>{description}</div>
        </div>
      </div>
    );

    const tabFilterAndButton = () => {
      return (
        <Row>
          <Col sm={4} md={4} lg={4} className="mb-2">
            {choiceCard(activeTab === 0, 'MAPPED GUARDIANS', 'Guardians are mapped with students', () =>
              this.toggle(0)
            )}
          </Col>
          <Col sm={4} md={4} lg={4} className="mb-2">
            {choiceCard(activeTab === 1, 'UNMAPPED GUARDIANS', 'Guardians are not mapped with students', () =>
              this.toggle(1)
            )}
          </Col>
          <Col sm={4} md={4} lg={4}>
            <CustomButton
              style={{ float: 'right' }}
              variant="contained"
              color="secondary"
              onClick={this.formModalOpen}
              name="Add Guardian"
            />
          </Col>
        </Row>
      );
    };
    return (
      <div className="content">
        {tabFilterAndButton()}
        <MuiTable
          tableHeaders={guardianTableHead}
          tableBodyData={{
            ...(!activeTab ? guardiansData : { content: unMappedGuardianList }),
            content: (!activeTab ? guardiansData?.content : unMappedGuardianList)?.map(el => ({
              ...el,
              name: (
                <span>
                  {el.name}{' '}
                  {el.email && <span style={{ color: usernameTextColor }}>({formUsernameFromEmail(el.email)})</span>}
                </span>
              ),
            })),
          }}
          bodyColumns={['relation', 'name', 'education', 'occupation', 'income', 'action']}
          dropDownActions={['edit', 'delete']}
          idName="guardianId"
          fetchItem={this.fetchGuardian}
          deleteItem={this.deleteGuardian}
          fetchPageData={this.fetchPageData}
          hidePagination={activeTab === 1}
          isLoading={guardiansFetching}
        />
        <GuardianFormModal
          isModalOpen={isModalOpen}
          formModalCloseProp={this.formModalClose}
          saveGuardian={this.saveGuardian}
          guardian={guardian}
          updateGuardian={this.updateGuardian}
          guardianUpdateSuccess={this.guardianUpdateSuccess}
        />
      </div>
    );
  }
}

const mapStateToProps = state => {
  return {
    loggedUserId: state.auth.loggedUserId,
    loggedUserToken: state.auth.loggedUserToken,
    schools: state.schools.schoolList,
    guardiansData: state.guardians.guardiansData,
    guardian: state.guardians.guardian,
    unMappedGuardianList: state.guardians.unMappedGuardianList,
  };
};

const mapDispatchToProps = dispatch => {
  return {
    fetchAllGuardians: data => dispatch(fetchAllGuardiansService(data)),
    saveGuardian: data => dispatch(saveGuardianService(data)),
    fetchGuardian: data => dispatch(fetchGuardianService(data)),
    updateGuardian: data => dispatch(updateGuardianService(data)),
    deleteGuardian: data => dispatch(deleteGuardianService(data)),
    fetchUnMappedGuardians: data => dispatch(fetchUnMappedGuardiansService(data)),
  };
};

export default connect(mapStateToProps, mapDispatchToProps)(GuardianPage);
